import React, { useState } from 'react';

// Create the App component here
const App = () => {
  // Initialize notes state here
  const [notes, setNotes] = useState([
    { id: 1, text: 'First note' },
    { id: 2, text: 'Second note' },
    { id: 3, text: 'Third note' }
  ]);

  // Initialize searchTerm state here
  const [searchTerm, setSearchTerm] = useState('');

  // Create addNote handler here
  const addNote = (text) => {
    const newNote = {
      id: notes.length + 1,
      text: text
    };
    setNotes([...notes, newNote]);
  };

  // Create deleteNote handler here
  const deleteNote = (id) => {
    setNotes(notes.filter(note => note.id !== id));
  };

  // Create updateNote handler here
  const updateNote = (id, newText) => {
    setNotes(notes.map(note => 
      note.id === id ? { ...note, text: newText } : note
    ));
  };

  // Create search handler here
  const handleSearch = (e) => {
    setSearchTerm(e.target.value);
  };

  // Filter notes based on search term
  const filteredNotes = notes.filter(note => 
    note.text.toLowerCase().includes(searchTerm.toLowerCase())
  );

  return (
    <div>
      {/* Add search input here */}
      <input 
        type="text" 
        placeholder="Search notes..." 
        value={searchTerm}
        onChange={handleSearch}
      />

      {/* Add note creation form here */}
      <form onSubmit={(e) => {
        e.preventDefault();
        const text = e.target.elements.noteText.value;
        if (text.trim()) {
          addNote(text);
          e.target.reset();
        }
      }}>
        <input 
          type="text" 
          name="noteText" 
          placeholder="Enter new note" 
        />
        <button type="submit">Add Note</button>
      </form>

      {/* Display filtered notes list here */}
      <ul>
        {filteredNotes.map(note => (
          <li key={note.id}>
            {note.text}
            {/* Add edit and delete buttons here */}
          </li>
        ))}
      </ul>
    </div>
  );
};

export default App;
